import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.DBSoX6Zw.js";const u=JSON.parse('{"title":"Architecture — CLI Client (client/)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/client.md","filePath":"architecture/client.md"}'),r={name:"architecture/client.md"};function d(n,e,c,s,l,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="architecture-—-cli-client-client" tabindex="-1">Architecture — CLI Client (<code>client/</code>) <a class="header-anchor" href="#architecture-—-cli-client-client" aria-label="Permalink to &quot;Architecture — CLI Client (\`client/\`)&quot;">​</a></h1><blockquote><p>The Plik command-line client. For system-wide overview, see the root <a href="./system.html">ARCHITECTURE.md</a>.</p></blockquote><hr><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client/</span></span>
<span class="line"><span>├── plik.go          ← entry point: arg parsing, config loading, dispatch</span></span>
<span class="line"><span>├── app.go           ← PlikCLI struct: upload flow, helpers (Run, info, getFileCommand, printf)</span></span>
<span class="line"><span>├── mcp.go           ← MCP (Model Context Protocol) server over stdio for AI assistants</span></span>
<span class="line"><span>├── config.go        ← configuration loading (.plikrc)</span></span>
<span class="line"><span>├── config_test.go   ← unit tests for config parsing (TTL, password, flags, file loading)</span></span>
<span class="line"><span>├── login.go         ← CLI device auth flow (--login)</span></span>
<span class="line"><span>├── progress.go      ← upload progress bar</span></span>
<span class="line"><span>├── update.go        ← self-update mechanism (PlikCLI method)</span></span>
<span class="line"><span>├── update_test.go   ← unit tests for update flow (early exits, error handling)</span></span>
<span class="line"><span>├── archive/         ← archive backends (tar, zip) — errors via CloseWithError</span></span>
<span class="line"><span>├── crypto/          ← crypto backends (openssl, pgp, age) — errors via CloseWithError</span></span>
<span class="line"><span>├── setup_test.go    ← e2e test infrastructure (TestMain, server lifecycle, helpers)</span></span>
<span class="line"><span>├── z1_e2e_basics_test.go   ← basic CLI tests (info, debug, single/multi file, stdin)</span></span>
<span class="line"><span>├── z2_e2e_options_test.go  ← upload option tests (oneshot, ttl, quiet, JSON, etc.)</span></span>
<span class="line"><span>├── z3_e2e_archive_test.go  ← archive backend tests (tar, zip)</span></span>
<span class="line"><span>├── z4_e2e_crypto_test.go   ← crypto backend tests (openssl, pgp, age)</span></span>
<span class="line"><span>├── z5_e2e_profiles_test.go ← profile e2e tests (upload, inheritance, info)</span></span>
<span class="line"><span>├── .plikrc          ← example client configuration</span></span>
<span class="line"><span>└── plik.sh          ← bash upload wrapper</span></span></code></pre></div><hr><h2 id="key-components" tabindex="-1">Key Components <a class="header-anchor" href="#key-components" aria-label="Permalink to &quot;Key Components&quot;">​</a></h2><h3 id="cli-entry-point-plik-go-and-runtime-state-app-go" tabindex="-1">CLI Entry Point (<code>plik.go</code>) and Runtime State (<code>app.go</code>) <a class="header-anchor" href="#cli-entry-point-plik-go-and-runtime-state-app-go" aria-label="Permalink to &quot;CLI Entry Point (\`plik.go\`) and Runtime State (\`app.go\`)&quot;">​</a></h3><p><code>plik.go</code> is a slim <code>main()</code> using <a href="https://github.com/docopt/docopt-go" target="_blank" rel="noreferrer">docopt-go</a> for argument parsing. It delegates all upload logic to the <code>PlikCLI</code> struct defined in <code>app.go</code>.</p><p><strong><code>PlikCLI</code> struct</strong> encapsulates all mutable runtime state:</p><ul><li><code>Config</code>, <code>Arguments</code> — parsed configuration and CLI args</li><li><code>ArchiveBackend</code>, <code>CryptoBackend</code> — initialized lazily during <code>Run()</code></li><li><code>Stdout</code>, <code>Stderr</code> — injectable <code>io.Writer</code> for output (default: <code>os.Stdout</code>/<code>os.Stderr</code>); enables test output capture without global state mutation</li></ul><p><strong><code>main()</code> flow</strong> (in <code>plik.go</code>):</p><ol><li>Parse CLI args → early exits: <code>--version</code>, <code>--mcp</code>, <code>--info</code>, <code>--login</code></li><li>Load config from <code>.plikrc</code> → <code>NewPlikCLI(config, args)</code><ul><li>First-run wizard is skipped when <code>--quiet</code>, <code>--yes</code>, or <code>--server</code> is set</li></ul></li><li>Dispatch to <code>cli.Run(client)</code> for the upload flow</li></ol><p><strong>Early-exit flags</strong> (handled before <code>cli.Run</code>):</p><ul><li><code>--version</code>, <code>--help</code> — print and exit</li><li><code>--mcp</code> — start MCP server over stdio</li><li><code>--info</code> — print client/server info</li><li><code>--update</code> — self-update binary</li><li><code>--login</code> — device auth flow, saves token via surgical patch</li><li><code>--update-plikrc</code> — rewrite config in canonical format (<code>updatePlikrc()</code> in <code>config.go</code>)</li></ul><p><strong><code>PlikCLI.Run()</code> flow</strong> (in <code>app.go</code>):</p><ol><li>Create upload via the Go library (<code>plik/</code>)</li><li>Add files (with optional archive/encrypt preprocessing)</li><li>Upload files with progress bars</li><li>Output results: <ul><li>Default: print download URLs/commands to stdout</li><li><code>--quiet</code>: print only file URLs to stdout</li><li><code>--json</code>: print <code>UploadWithURL</code> as pretty-printed JSON to stdout (implies <code>--quiet</code>)</li></ul></li></ol><h3 id="configuration-config-go" tabindex="-1">Configuration (<code>config.go</code>) <a class="header-anchor" href="#configuration-config-go" aria-label="Permalink to &quot;Configuration (\`config.go\`)&quot;">​</a></h3><p>Config is a TOML file loaded from (in order):</p><ol><li><code>PLIKRC</code> environment variable</li><li><code>~/.plikrc</code></li><li><code>/etc/plik/plikrc</code></li></ol><p><code>CliConfig</code> fields are grouped logically: Server, Upload defaults, Authentication, Archive, Encryption, Output, Behavior, Runtime. This order determines both the struct layout and the TOML serialization order produced by <code>writeConfig()</code>.</p><p><strong><code>writeConfig()</code></strong> produces human-readable, commented TOML matching the <code>.plikrc</code> template format. It writes all scalar fields first, then <code>[Table]</code> sections (<code>[ArchiveOptions]</code>, <code>[SecureOptions]</code>, <code>[Profiles.*]</code>) — this ordering is required by TOML spec. The <code>configLine()</code> helper handles column-aligned inline comments. Used by the first-run wizard and <code>saveConfig()</code> for creating new config files.</p><p><strong><code>WritePlikrcTemplate()</code></strong> generates the canonical <code>client/.plikrc</code> reference template. It calls <code>writeConfig()</code> with showcase defaults (DRY — same code path, different values). The <code>TestPlikrcTemplate_UpToDate</code> test compares the generated output against the committed file and rewrites it if stale. CI catches drift via <code>git diff --exit-code</code>.</p><h4 id="multi-profile-support" tabindex="-1">Multi-Profile Support <a class="header-anchor" href="#multi-profile-support" aria-label="Permalink to &quot;Multi-Profile Support&quot;">​</a></h4><p>The config file supports named profiles via <code>[Profiles.&lt;name&gt;]</code> TOML sections. Each profile can override any subset of the top-level fields. An on-disk config file is represented by <code>PlikrcFile</code>, which embeds <code>CliConfig</code> (base fields) plus <code>Profiles map[string]CliConfig</code> and <code>DefaultProfile string</code>.</p><p><strong>Profile selection precedence</strong> (highest to lowest):</p><ol><li><code>--profile</code> / <code>-P</code> CLI flag (supports comma-separated names for composition)</li><li><code>PLIK_PROFILE</code> environment variable (also supports comma-separated names)</li><li><code>DefaultProfile</code> field in config file (also supports comma-separated names)</li></ol><p><strong>Profile composition</strong>: <code>plik -P work,zip</code> applies profiles left-to-right over the base config. Last one wins on conflicts; non-overlapping fields from all profiles survive. Implemented via <code>parseProfiles()</code> (split + trim + dedup) and the composition loop in <code>LoadConfigFromFile</code>.</p><p><strong>Config layering</strong> (highest to lowest):</p><ol><li>CLI flags (<code>--server</code>, <code>--token</code>, etc.)</li><li>Selected profile(s) fields (composed left-to-right)</li><li>Top-level config fields</li><li>Built-in defaults (<code>NewUploadConfig()</code>)</li></ol><p><strong>Merge semantics</strong>: <code>mergeProfile()</code> uses <code>toml.MetaData.IsDefined()</code> to apply only fields explicitly set in the profile section. This distinguishes &quot;not present&quot; from &quot;set to zero value&quot; (e.g., <code>Token = &quot;&quot;</code> in a profile clears the base token). <code>validateProfile()</code> enforces that any profile defining <code>URL</code> must also define <code>Token</code> to prevent credential leakage to a different server. Similarly, <code>--server</code> in <code>UnmarshalArgs</code> clears the token (re-settable with <code>--token</code>).</p><p><strong>Key helpers</strong>:</p><ul><li><code>parseProfiles(input string) []string</code> — splits a comma-separated profile string into a deduplicated ordered list. Trims whitespace, drops empty segments.</li><li><code>SingleProfile() (string, error)</code> — returns the single active profile name, or errors if multiple profiles are active. Used as the DRY gate by <code>--login</code> (in <code>plik.go</code>) and <code>saveToken</code> (in <code>login.go</code>) which require exactly one profile to know where to write the token.</li><li><code>NewClient(name string) *plik.Client</code> — creates a <code>plik.Client</code> from the config with all upload defaults (<code>Token</code>, <code>Stream</code>, <code>OneShot</code>, <code>Removable</code>, <code>TTL</code>, <code>ExtendTTL</code>, <code>Comments</code>, <code>Login</code>, <code>Password</code>) set on the client. <code>plik.Client.NewUpload()</code> inherits these automatically via the embedded <code>*UploadParams</code> copy. Used by <code>plik.go</code> (CLI), <code>mcp.go</code> (MCP server), and test helpers.</li></ul><p>The runtime <code>CliConfig</code> carries <code>ActiveProfiles []string</code> (the resolved profile name(s)), <code>ProfileSource string</code> (<code>&quot;flag&quot;</code> from <code>-P</code>, <code>&quot;env&quot;</code> from <code>PLIK_PROFILE</code>, <code>&quot;default&quot;</code> from <code>DefaultProfile</code>, or <code>&quot;&quot;</code> for none), and <code>AvailableProfiles []string</code> (list of all profiles defined in the config) — all are <code>toml:&quot;-&quot;</code> and not serialized. <code>DefaultProfile string</code> (the file-level default) stays a plain string in the config struct. The MCP safety gate only locks profile switching when <code>ProfileSource == &quot;flag&quot;</code> (explicit <code>-P</code>); <code>DefaultProfile</code> does not lock.</p><p>Existing flat configs (no <code>[Profiles]</code> sections) are 100% backward compatible.</p><h3 id="cli-login-login-go" tabindex="-1">CLI Login (<code>login.go</code>) <a class="header-anchor" href="#cli-login-login-go" aria-label="Permalink to &quot;CLI Login (\`login.go\`)&quot;">​</a></h3><p>Implements a device authorization flow for CLI authentication:</p><ol><li>POST <code>/auth/cli/init</code> with hostname → receives a code, secret, and verification URL</li><li>Opens verification URL in user&#39;s browser (best-effort)</li><li>Polls POST <code>/auth/cli/poll</code> with code + secret every 2s</li><li>On approval, saves the token to <code>~/.plikrc</code> via surgical text patching (<code>patchToken</code>) that preserves user comments and profile ordering, then exits</li></ol><p><code>saveToken()</code> performs an in-place edit of the raw config file bytes — it finds the correct <code>Token = &quot;...&quot;</code> line (top-level or inside <code>[Profiles.&lt;name&gt;]</code>) and replaces only its value. If no Token line exists, one is inserted after the URL line (if present), otherwise right after the section header. This avoids the full-file rewrite that <code>writeConfig()</code> would produce.</p><p><strong><code>--update-plikrc</code></strong> is the intentional counterpart: it calls <code>loadPlikrc()</code> → <code>saveConfig()</code> to rewrite the entire file in canonical format, preserving all values and profile definitions but replacing custom comments with standard inline comments. A <code>[y/N]</code> confirmation prompt is shown unless <code>--yes</code> is set.</p><p>Triggered by <code>--login</code> flag or interactively during first-run when auth is enabled/forced. When <code>--login</code> is set, the first-run wizard skips its own interactive login to avoid triggering the flow twice.</p><h3 id="archive-backends-archive" tabindex="-1">Archive Backends (<code>archive/</code>) <a class="header-anchor" href="#archive-backends-archive" aria-label="Permalink to &quot;Archive Backends (\`archive/\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Backend</th><th>Description</th></tr></thead><tbody><tr><td><code>tar</code></td><td>Create tar archives with compression (gzip, bzip2, xz, lzip, lzma, lzop)</td></tr><tr><td><code>zip</code></td><td>Create zip archives</td></tr></tbody></table><p>Archives wrap multiple files/directories into a single upload file. Errors are propagated via <code>io.PipeWriter.CloseWithError()</code> from the archiving goroutine.</p><p><strong>Binary discovery</strong>: All backends that shell out to external commands (tar, zip, openssl) use <code>binutil.LookupBinary(configured, name)</code> which first checks <code>os.Stat(configured)</code> and falls back to <code>exec.LookPath(name)</code>. This handles cross-platform binary locations (e.g. <code>/bin/tar</code> vs <code>/usr/bin/tar</code>, macOS Homebrew paths).</p><h3 id="crypto-backends-crypto" tabindex="-1">Crypto Backends (<code>crypto/</code>) <a class="header-anchor" href="#crypto-backends-crypto" aria-label="Permalink to &quot;Crypto Backends (\`crypto/\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Backend</th><th>Description</th></tr></thead><tbody><tr><td><code>openssl</code></td><td>Symmetric encryption via OpenSSL CLI (configurable cipher). Uses <code>binutil.LookupBinary</code> for portable binary discovery. <strong>Deprecated</strong> — use <code>age</code> instead</td></tr><tr><td><code>pgp</code></td><td>Asymmetric encryption using pure Go <code>openpgp</code> (no external gpg binary needed). Keyring path respects <code>$GNUPGHOME</code> (default: <code>~/.gnupg/pubring.gpg</code>). <strong>Deprecated</strong> — use <code>age</code> instead</td></tr><tr><td><code>age</code></td><td>Modern encryption via <a href="https://age-encryption.org/" target="_blank" rel="noreferrer">age</a>. Supports passphrase, X25519, SSH recipients (<code>@github_user</code>, URL, raw key), and SSH host key scanning (<code>ssh://hostname</code>). URLs can serve SSH keys <strong>and</strong> native <code>age1…</code> recipients. Plain HTTP URLs trigger a MITM security prompt (default: decline). <strong>Default backend.</strong> Sets <code>upload.E2EE = &quot;age&quot;</code> for webapp interop (passphrase mode only)</td></tr></tbody></table><p>Encryption wraps the file data stream before upload. Errors are propagated via <code>io.PipeWriter.CloseWithError()</code> from the encryption goroutine. All backends expose a <code>Stderr io.Writer</code> field (default: <code>os.Stderr</code>) and a <code>SetStderr(w io.Writer)</code> method so that <code>PlikCLI</code> can redirect diagnostic output (passphrase display, recipient resolution progress, warnings) through its injectable writer for test capture.</p><p>When the <code>age</code> backend is used, the upload is flagged as E2EE (<code>upload.E2EE = &quot;age&quot;</code>). This tells the webapp to prompt for a passphrase on download and decrypt client-side. A cryptographically-secure passphrase is auto-generated when none is provided.</p><h3 id="self-update-update-go" tabindex="-1">Self-Update (<code>update.go</code>) <a class="header-anchor" href="#self-update-update-go" aria-label="Permalink to &quot;Self-Update (\`update.go\`)&quot;">​</a></h3><p>The client can update itself by downloading the latest matching binary from the configured Plik server. It compares versions and replaces the current binary in-place. Between the current and target versions, the client displays changelogs from the releases list. If the client&#39;s current version is not found in the list (e.g. RC upgrading to stable), only the target version&#39;s changelog is shown.</p><h3 id="mcp-server-mcp-go" tabindex="-1">MCP Server (<code>mcp.go</code>) <a class="header-anchor" href="#mcp-server-mcp-go" aria-label="Permalink to &quot;MCP Server (\`mcp.go\`)&quot;">​</a></h3><p>Implements a local <a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol</a> server over stdio, enabling AI coding assistants (Cursor, VS Code Copilot, etc.) to upload files via Plik. Activated by <code>plik --mcp</code>.</p><p>Uses the official <a href="https://github.com/modelcontextprotocol/go-sdk" target="_blank" rel="noreferrer">Go MCP SDK</a> (<code>mcp.StdioTransport</code>) and the <code>plik/</code> Go library for uploads.</p><p><strong>Tools:</strong></p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>upload_text</code></td><td>Upload inline text content as a named file</td></tr><tr><td><code>upload_file</code></td><td>Upload a single file by path</td></tr><tr><td><code>upload_files</code></td><td>Upload multiple files by paths in a single upload</td></tr><tr><td><code>server_info</code></td><td>Get server version, config, capabilities, and profile info</td></tr><tr><td><code>list_profiles</code></td><td>List available profiles from <code>~/.plikrc</code> with their URLs</td></tr></tbody></table><p><strong>Prompts:</strong> <code>upload_guide</code></p><p><strong>Profile awareness:</strong> All upload tools accept an optional <code>profile</code> parameter to target a different server. <code>clientForProfile()</code> always re-reads <code>~/.plikrc</code> from disk on every tool call, so edits (token rotation, URL changes, <code>--login</code>) take effect immediately without restarting the MCP server. It builds a <code>plik.Client</code> via <code>cfg.NewClient()</code>, which carries over all upload defaults (OneShot, TTL, Token, etc.) from the resolved config. <code>Stream</code> is cleared before creating the client to prevent indefinite blocking.</p><p><strong>Safety gate:</strong> If the MCP server is started with <code>-P &lt;profile&gt;</code> (<code>ProfileSource == &quot;flag&quot;</code>), the <code>profile</code> parameter on tools is rejected — the server is locked to the startup profile(s). <code>DefaultProfile</code> and <code>PLIK_PROFILE</code> env do not lock.</p><p><strong><code>loadPlikrc()</code></strong> (in <code>config.go</code>): Factored out of <code>LoadConfigFromFile</code> to allow <code>list_profiles</code> to read profile definitions without triggering the full resolution/merge logic.</p><hr><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><h3 id="unit-tests" tabindex="-1">Unit Tests <a class="header-anchor" href="#unit-tests" aria-label="Permalink to &quot;Unit Tests&quot;">​</a></h3><ul><li><code>config_test.go</code> — TTL parsing, password splitting, boolean flags, config file loading, defaults</li><li><code>update_test.go</code> — auto-update disabled, quiet mode, unreachable server, missing platform binary</li><li><code>crypto/age/age_test.go</code> — recipient resolution, encryption round-trips</li></ul><h3 id="integration-tests-e2e" tabindex="-1">Integration Tests (e2e) <a class="header-anchor" href="#integration-tests-e2e" aria-label="Permalink to &quot;Integration Tests (e2e)&quot;">​</a></h3><p>End-to-end tests run against an ephemeral <code>plikd</code> server (started in <code>TestMain</code>):</p><table tabindex="0"><thead><tr><th>File</th><th>Coverage</th></tr></thead><tbody><tr><td><code>setup_test.go</code></td><td>Server lifecycle, helpers</td></tr><tr><td><code>z1_e2e_basics_test.go</code></td><td>Info, debug, single/multi file, custom name, stdin</td></tr><tr><td><code>z2_e2e_options_test.go</code></td><td>Oneshot, removable, stream, TTL, password, comments, quiet, JSON, not-secure, error paths</td></tr><tr><td><code>z3_e2e_archive_test.go</code></td><td>Tar (single, multi, dir, compression, options, name), zip (single, dir, options, name, dir+name)</td></tr><tr><td><code>z4_e2e_crypto_test.go</code></td><td>OpenSSL (auto/custom/prompted passphrase + decrypt round-trip, cipher, options), PGP (encrypt+decrypt), Age (passphrase + decrypt round-trip, recipient + decrypt)</td></tr><tr><td><code>z5_e2e_profiles_test.go</code></td><td>Profile upload (settings flow through), base config inheritance, info output with/without profiles</td></tr></tbody></table><p>Tests requiring external binaries (<code>tar</code>, <code>zip</code>, <code>gpg</code>, <code>age</code>, <code>openssl</code>) use <code>requireBinary()</code> to fail immediately if unavailable.</p><hr><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><h3 id="stderr-for-all-non-data-output" tabindex="-1">Stderr for all non-data output <a class="header-anchor" href="#stderr-for-all-non-data-output" aria-label="Permalink to &quot;Stderr for all non-data output&quot;">​</a></h3><p>Because <code>--quiet</code> and <code>--json</code> modes reserve stdout exclusively for machine-readable data (file URLs or JSON), <strong>all</strong> informational, diagnostic, and error messages in the CLI must be written to <strong>stderr</strong> (<code>fmt.Fprintf(os.Stderr, ...)</code>). This includes:</p><ul><li>Passphrase display (crypto backends)</li><li>Recipient resolution progress (age backend)</li><li>Debug output</li><li>Streaming download commands</li><li>Archive/crypto error messages</li><li>Progress bars (already write to stderr via the <code>pb</code> library)</li></ul><p>Never use <code>fmt.Printf</code> / <code>fmt.Println</code> for non-data output in the CLI.</p>`,74)])])}const h=o(r,[["render",d]]);export{u as __pageData,h as default};
